const BOT_USERNAME = 'zaidinfo_bot'.toLowerCase();

const output = [];

for (const item of $input.all()) {
  const msg = item.json.message || item.json.channel_post || item.json;
  const text = msg.text || msg.caption || '';

  // 1. Reply / Quote Detection
  const replyTo = msg.reply_to_message || null;
  const quote = msg.quote || null; 
  const externalReply = msg.external_reply || null;

  let replyText = null;
  if (quote && quote.text) {
    replyText = quote.text;
  } else if (replyTo) {
    replyText = replyTo.text || replyTo.caption || null;
  }

  // 2. Mention & Command Detection
  let isBotMentioned = text.toLowerCase().includes(`@${BOT_USERNAME}`);
  const entities = msg.entities || msg.caption_entities || [];
  if (!isBotMentioned && entities.length > 0) {
    isBotMentioned = entities.some(e => 
      (e.type === 'mention' || e.type === 'bot_command') && 
      text.substring(e.offset, e.offset + e.length).toLowerCase().includes(BOT_USERNAME)
    );
  }

  const hasReportCommand = text.toLowerCase().includes('/report');
  const isReply = replyTo !== null || quote !== null || externalReply !== null;
  const isReport = isBotMentioned && isReply && hasReportCommand;

  // --- UPDATED: Question Detection & Cleanup ---
  // A question is any message mentioning the bot that is NOT a report
  const isQuestion = isBotMentioned && !isReport;

  let questionText = null;
  if (isQuestion) {
    questionText = text
      .replace(new RegExp(`@${BOT_USERNAME}`, 'gi'), '') // Removes the bot mention
      .trim(); // Cleans up extra spaces
  }

  // 3. Offender Info (Mike)
  let offenderId = null, offenderName = null, offenderUsername = null;
  if (replyTo && replyTo.from) {
    offenderId = replyTo.from.id;
    offenderName = replyTo.from.first_name;
    offenderUsername = replyTo.from.username;
  } else if (externalReply && externalReply.origin && externalReply.origin.sender_user) {
    offenderId = externalReply.origin.sender_user.id;
    offenderName = externalReply.origin.sender_user.first_name;
    offenderUsername = externalReply.origin.sender_user.username;
  }

  // 4. New Member Detection
  const newMembers = msg.new_chat_members || (msg.new_chat_participant ? [msg.new_chat_participant] : []);
  const isNewMember = newMembers.length > 0;

  const firstNewMember = isNewMember ? newMembers[0] : null;
  const newMemberId = firstNewMember ? firstNewMember.id : null;
  const newMemberName = firstNewMember 
    ? `${firstNewMember.first_name || ''} ${firstNewMember.last_name || ''}`.trim() 
    : null;
  const newMemberUsername = firstNewMember ? firstNewMember.username || null : null;
  const isNewMemberBot = firstNewMember ? Boolean(firstNewMember.is_bot) : false;

  // 5. Final Output Object
  output.push({
    json: {
      // Logic Flags
      isBotMentioned: isBotMentioned,
      isReply: isReply,
      hasReportCommand: hasReportCommand,
      isReport: isReport,
      isNewMember: isNewMember,
      isQuestion: isQuestion,

      // Messages
      messageText: text,
      replyText: replyText,
      questionText: questionText,

      // Reporter Details
      reporterId: msg.from ? msg.from.id : null,
      reporterName: msg.from ? msg.from.first_name : null,
      reporterUsername: msg.from ? msg.from.username : null,

      // Offender Details
      offenderId: offenderId,
      offenderName: offenderName,
      offenderUsername: offenderUsername,

      // New Member Details
      newMemberId: newMemberId,
      newMemberName: newMemberName,
      newMemberUsername: newMemberUsername,
      isNewMemberBot: isNewMemberBot,

      // Chat & Identifiers
      chatId: msg.chat ? msg.chat.id : null,
      messageId: msg.message_id || null,
      replyMessageId: replyTo ? replyTo.message_id : null
    }
  });
}

return output;
